text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Sana. How can I help you today?",
      "tags": ["greeting"]
    },
    {
      "speaker": "customer",
      "text": "Hi Sana, I'm calling because my new phone has been dropping calls every single hour. It's incredibly frustrating.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am sorry to hear that you are experiencing these dropped calls. I can certainly look into this for you.",
      "tags": ["empathy"]
    },
    {
      "speaker": "agent",
      "text": "Before we dive into the account details, could you please provide your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Sure, it is 75745233. My name is James Sharma.",
      "tags": ["identity_verification"]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Mr. Sharma. And just to confirm, what is the phone number associated with the account?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is 95173 72493. I live at 130 Station Road.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Thank you for that information. Let me check the network status in your area.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I've already done that on your website and it says everything is fine. I just want this device to work properly.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I understand. Please try restarting your device now while I stay on the line.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I have restarted it five times today already! This is a waste of my time. I am tired of this poor service.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I apologize for the inconvenience. Let me check if there are any firmware updates available for your handset.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "This is ridiculous. If you can't fix this right now, I'm going to cancel my contract and switch to another provider.",
      "tags": ["churn_signal"]
    },
    {
      "speaker": "agent",
      "text": "I see. I will need to run a remote diagnostic on your device to see what is happening.",
      "tags": ["action:diagnostic"]
    }
  ]
}
